import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card } from 'react-bootstrap';

const Home = ({ user }) => {
  const navigate = useNavigate();

  useEffect(() => {
    if (user && user.role === 'admin') {
      navigate('/admin-dashboard');
    }
  }, [user, navigate]);

  if (user && user.role === 'admin') {
    return null; // Render nothing if the user is an admin
  }

  return (
    <Container className="mt-4">
      <h1 className="text-center">Welcome to Event Manager</h1>
      <Row className="mt-4">
        <Col md={4}>
          <Card className="mb-4">
            <Card.Body>
              <Card.Title>Upcoming Events</Card.Title>
              <Card.Text>
                Check out the upcoming events and register for the ones you are interested in.
              </Card.Text>
              <Card.Link href="/events">View Events</Card.Link>
            </Card.Body>
          </Card>
        </Col>
        <Col md={4}>
          <Card className="mb-4">
            <Card.Body>
              <Card.Title>My Events</Card.Title>
              <Card.Text>
                View and manage the events you have registered for.
              </Card.Text>
              <Card.Link href="/my-events">My Events</Card.Link>
            </Card.Body>
          </Card>
        </Col>
        <Col md={4}>
          <Card className="mb-4">
            <Card.Body>
              <Card.Title>Contact Us</Card.Title>
              <Card.Text>
                Have any questions or need support? Get in touch with us.
              </Card.Text>
              <Card.Link href="/contact">Contact Us</Card.Link>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default Home;
